"""VAD helpers — backends are invoked via ASR pipelines; catalog ids documented here."""

from .options import (
    AGGRESSIVE_THRESHOLD,
    DEFAULT_THRESHOLD,
    FILM_THRESHOLD,
    SENSITIVE_THRESHOLD,
    normalize_vad_options,
    sensevoice_merge_length_s,
    sensevoice_vad_kwargs,
    whisper_vad_kwargs,
)

DEFAULT_VAD_FOR_SENSEVOICE = "fsmn-vad"
DEFAULT_VAD_FOR_WHISPER = "silero-vad"
WHISPERSEG_VAD_ID = "whisperseg-asmr"
FIRERED_VAD_ID = "firered-vad"


def remap_vad_for_sensevoice(vad_model: str | None) -> str:
    """FunASR AutoModel only loads catalog fsmn-vad (not TEN / FireRed / Silero / WhisperSeg)."""
    raw = str(vad_model or "").strip()
    vad_l = raw.lower().replace("_", "-")
    if not vad_l:
        return DEFAULT_VAD_FOR_SENSEVOICE
    if (
        "whisperseg" in vad_l
        or vad_l.startswith("silero")
        or "firered" in vad_l
        or vad_l in ("ten", "ten-vad")
        or vad_l.startswith("ten-")
    ):
        return DEFAULT_VAD_FOR_SENSEVOICE
    return raw


